BEGIN;
-- Separate six-table ACL corrective BODY. No product migration timestamp assigned.
-- REQUIRED ORDER: exact reviewed fifth-review policy first, fresh metadata review, then this ACL body.
-- Root must verify correct Supabase project and give separate actual operation GO.
-- Only twelve direct ordinary-role TRUNCATE grants change; no table-content SQL.
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='15s';
SET LOCAL search_path=pg_catalog,public;
SET LOCAL TIME ZONE 'UTC';
DO $actor$ BEGIN IF current_user<>'postgres' THEN RAISE EXCEPTION 'ACL_REVIEWED_POSTGRES_EXECUTOR_REQUIRED'; END IF; END $actor$;
-- Parent first, remaining five fixed alphabetical order; one transaction, bounded lock wait.
LOCK TABLE public.recipes,public.recipe_ingredients,public.recipe_media,public.recipe_reviews,public.recipe_steps,public.recipe_submissions IN ACCESS EXCLUSIVE MODE;
CREATE TEMP TABLE kitchen_acl_scope_marker(dummy boolean) ON COMMIT DROP;
CREATE OR REPLACE FUNCTION pg_temp.kitchen_six_table_acl_state() RETURNS jsonb LANGUAGE sql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,public AS $capture$
SELECT jsonb_build_object(
 'roles',(SELECT jsonb_agg(jsonb_build_object('role',rolname,'login',rolcanlogin,'bypassrls',rolbypassrls,'superuser',rolsuper) ORDER BY rolname COLLATE "C") FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')),
 'tables',(SELECT jsonb_agg(jsonb_build_object(
  'table',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,
  'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable)
    ORDER BY (CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END) COLLATE "C",pg_get_userbyid(x.grantor) COLLATE "C",x.privilege_type COLLATE "C",x.is_grantable),'[]'::jsonb)
    FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x),
  'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('cmd',p.cmd,'name',p.policyname,'qual',p.qual,'roles',p.roles,'permissive',p.permissive,'with_check',p.with_check) ORDER BY p.policyname COLLATE "C"),'[]'::jsonb) FROM pg_policies p WHERE p.schemaname='public' AND p.tablename=c.relname),
  'effective_truncate',jsonb_build_object('anon',has_table_privilege('anon',c.oid,'TRUNCATE'),'authenticated',has_table_privilege('authenticated',c.oid,'TRUNCATE'),'service_role',has_table_privilege('service_role',c.oid,'TRUNCATE')),
  'column_acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('attnum',at.attnum,'column',at.attname,'acl',CASE WHEN at.attacl IS NULL THEN NULL ELSE (SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN z.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(z.grantee) END,'grantor',pg_get_userbyid(z.grantor),'privilege',z.privilege_type,'grantable',z.is_grantable)
    ORDER BY (CASE WHEN z.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(z.grantee) END) COLLATE "C",pg_get_userbyid(z.grantor) COLLATE "C",z.privilege_type COLLATE "C",z.is_grantable),'[]'::jsonb) FROM aclexplode(at.attacl) z) END) ORDER BY at.attnum),'[]'::jsonb) FROM pg_attribute at WHERE at.attrelid=c.oid AND at.attnum>0 AND NOT at.attisdropped))
  ORDER BY c.relname COLLATE "C") FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND c.relname IN ('recipes','recipe_ingredients','recipe_steps','recipe_media','recipe_reviews','recipe_submissions')))
;
$capture$;
DO $acl_change$
