 expected_after jsonb; actual_before jsonb; actual_after jsonb; columns_before jsonb; columns_after jsonb; constraints_before jsonb; constraints_after jsonb;
BEGIN
 SELECT jsonb_set(expected_before,'{tables}',jsonb_agg(t.value || jsonb_build_object('acl',(SELECT jsonb_agg(a.value ORDER BY a.ord) FROM jsonb_array_elements(t.value->'acl') WITH ORDINALITY a(value,ord) WHERE NOT(a.value->>'grantee' IN ('anon','authenticated') AND a.value->>'privilege'='TRUNCATE')),'effective_truncate',jsonb_build_object('anon',false,'authenticated',false,'service_role',true)) ORDER BY t.value->>'table')) INTO expected_after FROM jsonb_array_elements(expected_before->'tables') t;
 actual_before:=pg_temp.kitchen_six_table_acl_state();
 IF actual_before=expected_after THEN
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(actual_before->'tables') t WHERE (t->'effective_truncate'->>'anon')::boolean OR (t->'effective_truncate'->>'authenticated')::boolean) THEN RAISE EXCEPTION 'ACL_EFFECTIVE_TRUNCATE_STILL_PRESENT'; END IF;
  RAISE NOTICE 'ACL_TRUNCATE_NO_CHANGE_EXACT_REPLAY'; RETURN;
 END IF;
 IF actual_before IS DISTINCT FROM expected_before THEN RAISE EXCEPTION 'ACL_EXACT_PRESTATE_DRIFT_OR_FIFTH_POLICY_NOT_APPLIED'; END IF;
 SELECT (SELECT jsonb_agg(to_jsonb(i) ORDER BY table_name COLLATE "C",ordinal_position) FROM information_schema.columns i WHERE table_schema='public' AND table_name IN ('recipes','recipe_ingredients','recipe_steps','recipe_media','recipe_reviews','recipe_submissions')) INTO columns_before;
 SELECT (SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype::text,'definition',pg_get_constraintdef(k.oid)) ORDER BY c.relname COLLATE "C",k.conname COLLATE "C"),'[]'::jsonb) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('recipes','recipe_ingredients','recipe_steps','recipe_media','recipe_reviews','recipe_submissions')) INTO constraints_before;
 REVOKE TRUNCATE ON TABLE public.recipes,public.recipe_ingredients,public.recipe_media,public.recipe_reviews,public.recipe_steps,public.recipe_submissions FROM anon,authenticated;
 -- SYNTHETIC_TEST_AFTER_REVOKE_INSERT_POINT (never altered in actual operation body)
 actual_after:=pg_temp.kitchen_six_table_acl_state();
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(actual_after->'tables') t WHERE (t->'effective_truncate'->>'anon')::boolean OR (t->'effective_truncate'->>'authenticated')::boolean) THEN RAISE EXCEPTION 'ACL_EFFECTIVE_TRUNCATE_STILL_PRESENT_INCLUDING_INHERITANCE'; END IF;
 IF actual_after IS DISTINCT FROM expected_after THEN RAISE EXCEPTION 'ACL_UNEXPECTED_POSTSTATE'; END IF;
 SELECT (SELECT jsonb_agg(to_jsonb(i) ORDER BY table_name COLLATE "C",ordinal_position) FROM information_schema.columns i WHERE table_schema='public' AND table_name IN ('recipes','recipe_ingredients','recipe_steps','recipe_media','recipe_reviews','recipe_submissions')) INTO columns_after;
 SELECT (SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype::text,'definition',pg_get_constraintdef(k.oid)) ORDER BY c.relname COLLATE "C",k.conname COLLATE "C"),'[]'::jsonb) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('recipes','recipe_ingredients','recipe_steps','recipe_media','recipe_reviews','recipe_submissions')) INTO constraints_after;
 IF columns_after IS DISTINCT FROM columns_before OR constraints_after IS DISTINCT FROM constraints_before THEN RAISE EXCEPTION 'ACL_UNRELATED_COLUMN_OR_CONSTRAINT_DRIFT'; END IF;
 RAISE NOTICE 'ACL_TRUNCATE_APPLIED_EXACT_TWELVE_GRANTS';
END
$acl_change$;
